self.KB_CONTENT["card:751686"]={"id":"card:751686","ty":"card","sourceId":"751686","title":"『財務比率分析表』中的『選擇比較期數』為何？","ver":"iGP","topic":"分析表","keywords":["分析表","比率","比較","財務"],"y":"other","answer":"* 區分1.一期、2.二期、3.三期、4.四期及5.五期。* 視選擇比較期數的值，而可輸入第一期至第五期。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
