self.KB_CONTENT["card:783014"]={"id":"card:783014","ty":"card","sourceId":"783014","title":"『應付票據兌現整批作業』的作業重點有哪些？","ver":"GP4以上","topic":"應付","keywords":["應付","票據","整批"],"y":"explain","answer":"■作業重點1.依選擇條件按將資料產生於表身，並依到期日+票號排序，可再選擇全選或部份處理。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
