self.KB_CONTENT["card:782974"]={"id":"card:782974","ty":"card","sourceId":"782974","title":"『E-BOM變更單建立』中的『選配預設 (TK015)』為何？","ver":"GP4以上","topic":"變更單","keywords":["變更單","品號","屬性"],"y":"other","answer":"* 預設N。* 若主件品號屬性為 Feature/Option 件且選配預設值為 N，預設標準成本計算為 N。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
