self.KB_CONTENT["card:778517"]={"id":"card:778517","ty":"card","sourceId":"778517","title":"『LRPR05 品號供需明細表』中的『僅列印存在於計劃檔中的品號』為何？","ver":"GP4以上","topic":"明細表","keywords":["明細表","品號","採購","生產"],"y":"other","answer":"* 當僅列印存在於計劃檔中的品號為Y時，[生產計劃檔]、[採購計劃檔] 及 [選擇計劃批號] 欄位，才可輸入。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
