self.KB_CONTENT["card:778838"]={"id":"card:778838","ty":"card","sourceId":"778838","title":"『出貨通知單建立作業(IDL)』中的『序號 (TB003)』為何？","ver":"GP4以上","topic":"單位","keywords":["單位","序號","出貨","重複"],"y":"other","answer":"* 可修改。但不可為空白、不可重複。* 預設為每10號為跳號單位。例：0010、0020……* 序號欄位需輸入數字且不可小於四碼。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
