self.KB_CONTENT["card:756463"]={"id":"card:756463","ty":"card","sourceId":"756463","title":"『銷售預測(依類別)建立作業』的作業重點有哪些？","ver":"iGP","topic":"品號","keywords":["品號","訂單","狀態","權限"],"y":"explain","answer":"1.『：複製銷售預測』(icon)，此功能須有新增權限且新增狀態時執行。2.當訂單確認時，會依該品號所屬類別回寫銷售預測檔「已受訂量」。3.依類別的銷售預測資料不會影響LRP及MRP的計算","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
